// Keep broken links (and warnings if asked) and write one plain-text e-mail. No problems: no e-mail.
const cfg = $('Configure').first().json;
const keep = cfg.includeWarnings ? ['error', 'warning'] : ['error'];
const rows = $input.all().map(i => i.json).filter(r => keep.includes(r.severity));
if (!rows.length) return [];
const lines = rows.slice(0, 100).map(r => {
  const where = (r.foundOn || []).map(s => `    on ${s.page}${s.text ? ` ("${s.text}")` : ''}`).join('\n');
  return `- ${r.url}\n  ${r.status ?? ''} ${r.problem || ''} · ${r.linkType} ${r.kind || 'link'} · on ${r.foundOnCount || 1} page(s)\n${where}`;
});
const more = rows.length > 100 ? `\n...and ${rows.length - 100} more. Open the run in Apify Console for the full list.` : '';
return [{ json: {
  sendTo: cfg.sendTo,
  subject: `${rows.length} ${cfg.includeWarnings ? 'link problem(s)' : 'broken link(s)'} on ${new URL(cfg.siteUrl).hostname}`,
  text: `Weekly link check for ${cfg.siteUrl}\n\n${lines.join('\n\n')}${more}\n`,
} }];
